{
  "technical_and_design_decisions": [
    "Use Spring Boot's JarLauncher API as the foundation for the new ModuleLauncher contract, eliminating duplicated launch logic (U6).",
    "Implement a YARN ResourceManager REST client (instead of the legacy YARNClient API) for application submission, status polling, and lifecycle management (U2).",
    "Persist and serve application artifacts (YARN app definition archives) from HDFS so xd-admin can orchestrate deployments centrally (U1).",
    "Drive multi-instance configuration through Spring Cloud Data Flow deployment properties (e.g., module.*.yarn.app.name) parsed at the deployer level (U3).",
    "Adopt a CompletableFuture/TaskExecutor-based async deployer design so the shell returns immediately and operations are queued as YARN tasks (U4).",
    "Introduce a uniform external-library resolution abstraction (coordinate across Maven coordinates, file paths, and HDFS locations) feeding the Boot loader (U5, U8).",
    "Preserve backward compatibility with existing module deployer APIs and module packaging conventions while extending behaviour.",
    "Treat JarLauncher refactoring as a foundation dependency for U5, U7, and U8, so related work is sequenced after the refactor stabilises."
  ],
  "assumptions": [
    "A single experienced Spring/YARN developer performs all work; estimates are in 8-hour workdays.",
    "An existing Spring Cloud Data YARN code base (xd-admin, ModuleLauncher, AppDeployer) is available as the starting point; green-field effort is not required.",
    "Java 17+ toolchain and a working Hadoop/YARN test cluster (with HDFS) are available for development and verification.",
    "Unit tests, integration tests against a local YARN mini-cluster, and documentation are all in scope.",
    "No new infrastructure provisioning, CI/CD changes, or product-management overhead are included.",
    "No major changes are required to upstream Spring Boot; existing JarLauncher public API is sufficient.",
    "Authentication/security for the ResourceManager REST API uses standard Kerberos/SPNEGO patterns but is not the primary scope of this increment.",
    "Story points/effort scales are derived from comparable Spring Cloud Data YARN work and historical data-flow module development."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Study the existing xd-admin, ModuleLauncher, and YARN app deployer code; produce an architecture/design document covering HDFS staging, RM REST client, async deployer, multi-instance properties, and JarLauncher integration.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "HDFS-based YARN app deployment (U1)",
      "activity_description": "Implement HDFS artifact upload, manifest handling, and xd-admin orchestration so YARN applications are deployed automatically from the manifest.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "YARN ResourceManager REST API client (U2)",
      "activity_description": "Build a REST client to negotiate with the ResourceManager for module group deployment, including app-type (CLOUDDATA) and app-name (spring-cloud-data-yarn-app) handling, status polling, and error handling.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Multi-app instance support (U3)",
      "activity_description": "Add parsing/handling of deployment properties (module.*.yarn.app.name) to allow multiple YARN app instances with distinct queues, priorities, and runtime parameters.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Asynchronous deployer (U4)",
      "activity_description": "Refactor the deployer to operate asynchronously using a TaskExecutor/CompletableFuture model so the shell returns quickly and deployment tasks are queued within YARN.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "ModuleLauncher refactor on Spring Boot JarLauncher (U5, U6)",
      "activity_description": "Refactor the ModuleLauncher contract to delegate to Boot's JarLauncher API; remove duplicated launch functionality; keep behaviour-compatible with existing modules.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7",
      "activity_name": "External library resolution and Boot loader integration (U8)",
      "activity_description": "Design and implement a uniform mechanism to resolve and add module-dependent external JARs to the Boot loader so OOTB modules can consume third-party libraries consistently.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Unit and integration testing",
      "activity_description": "Write unit tests for all new components, integration tests against a YARN mini-cluster covering HDFS staging, RM REST submission, async flows, multi-instance, and Boot loader resolution; add test cases that document the JAR-to-Boot-loader flow (U7 test portion).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "Reference documentation (U7)",
      "activity_description": "Produce reference documentation and examples for resolving and adding JARs to the Boot loader, suitable as a porting reference for modules with external dependencies.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "End-to-end verification, hardening and finalization",
      "activity_description": "Run end-to-end deployment scenarios across stories U1–U8, fix cross-component defects, tighten logging/error reporting, and verify backward compatibility before sign-off.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 33
  }
}
```

